import{z as o,x as i,o as A,c as p,q as s,j as t,D as B,d as e,s as l,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"性能工程案例收束","description":"","frontmatter":{"title":"性能工程案例收束","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pe3-map.md","filePath":"cs/pe3-map.md","lastUpdated":1791413859000}'),m={name:"cs/pe3-map.md"};function c(d,E,C,D,f,h){const r=i("Mermaid");return A(),p("div",null,[E[2]||(E[2]=s('<h1 id="性能工程案例收束" tabindex="-1">性能工程案例收束 <a class="header-anchor" href="#性能工程案例收束" aria-label="Permalink to &quot;性能工程案例收束&quot;">​</a></h1><div class="epigraph"><p>性能工程的产出不是快，是每一句「快」都带着数字、负载与判据；判据缺席的地方，剩下的都是修辞。</p><footer>—— 据 Jain，The Art of Computer Systems Performance Analysis，1991；Beyer 等，Site Reliability Engineering，2016；Dean 与 Barroso，CACM 2013；本课程八课口径整理</footer></div><p><a href="/cs/pe3-cost-case">上一课</a>把性能与成本合进同一本账，在 SLO 约束下重新定价了安全水位。本课程到此收束：本课把七课拼回一张图——同一个 API 服务从接手到第二年大促的完整周期——并沉淀出换服务、换团队仍然成立的骨架，给主干课的机制课补上「落在一个真实服务上是什么样」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>收束要回答的是：哪些知识跟场景走、哪些不跟。不这么做会错在哪：把具体工具与数字当知识带走——「我们永远用七成水位」「必须用某款 profiler」「p99 一律 200 ms」——换一个负载形状、换一代硬件、换一个云，全部作废；而真正跨场景的纪律反而没人带走。收束把七课的对象各归到服务生命周期的位置上，看它们何时出场、向谁要证据。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按时间线走一遍。<strong>接手</strong>：<a href="/cs/pe3-requirements">第一课</a>把「系统要快一点」写成四件套——SLI、SLO、负载模型、验收协议；这是后面每一次测量都要回头对表的合同。<strong>搭测量</strong>：<a href="/cs/pe3-benchmark-pitfalls">基准课</a>的四环控制搭起内部基准与 CI 门禁；<a href="/cs/pe3-microbench-vs-real">第三课</a>定下分工——微基准选方案、端到端收账。<strong>第一次回归</strong>：<a href="/cs/pe3-regression-case">第四课</a>冻结现场、排除平台、二分到提交、差分归因、双收账结案。<strong>大促</strong>：<a href="/cs/pe3-capacity-case">第五课</a>测容量曲线取拐点水位、约束资源取最小、全链路演练预案。<strong>上线后</strong>：<a href="/cs/pe3-tail-latency-case">第六课</a>按时间、特征、实例三个维度切开分位，把惊群与排队两个来源对上同一时间轴。<strong>年底</strong>：<a href="/cs/pe3-cost-case">第七课</a>建每请求成本账，双赢点先做，水位在错误预算上重新定价。第二年负载形状变了，回到第一课重写负载模型——课程是一个环，不是一条线。</p><p><span class="marginnote">数字实例（Amdahl 的封顶）：一处占了总时间 60% 的热点，哪怕优化到零，整体也只剩 40% 的耗时——加速比封顶在 2.5 倍；而一处只占 5% 的代码，优化到零也只有约 5% 的收益。动手前先算占比，能拦下大半「很有激情但没用」的优化。</span></p>',8)),(A(),t(n,null,{default:B(()=>[l(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20START%5B%22%E6%8E%A5%E6%89%8B%EF%BC%9A%E6%8A%8A%E3%80%8E%E5%BF%AB%E3%80%8F%E5%86%99%E6%88%90%E5%9B%9B%E4%BB%B6%E5%A5%97%22%5D%20--%3E%20BENCH%5B%22%E6%90%AD%E6%B5%8B%E9%87%8F%EF%BC%9A%E5%9B%9B%E7%8E%AF%E5%9F%BA%E5%87%86%E4%B8%8E%20CI%20%E9%97%A8%E7%A6%81%22%5D%0A%20%20BENCH%20--%3E%20SPLIT%5B%22%E5%AE%9A%E5%88%86%E5%B7%A5%EF%BC%9A%E5%BE%AE%E5%9F%BA%E5%87%86%E9%80%89%E6%96%B9%E6%A1%88%EF%BC%8C%E7%AB%AF%E5%88%B0%E7%AB%AF%E6%94%B6%E8%B4%A6%22%5D%0A%20%20SPLIT%20--%3E%20REGR%5B%22%E5%9B%9E%E5%BD%92%E6%8E%92%E6%9F%A5%EF%BC%9A%E5%86%BB%E7%BB%93%E3%80%81%E4%BA%8C%E5%88%86%E3%80%81%E5%B7%AE%E5%88%86%22%5D%0A%20%20REGR%20--%3E%20CAP%5B%22%E5%AE%B9%E9%87%8F%E8%A7%84%E5%88%92%EF%BC%9A%E6%8B%90%E7%82%B9%E6%B0%B4%E4%BD%8D%E4%B8%8E%E5%85%A8%E9%93%BE%E8%B7%AF%E6%BC%94%E7%BB%83%22%5D%0A%20%20CAP%20--%3E%20TAIL%5B%22%E8%BF%BD%E7%8C%8E%E9%95%BF%E5%B0%BE%EF%BC%9A%E4%B8%89%E7%BB%B4%E5%88%87%E5%88%86%E4%B8%8E%E6%9C%BA%E5%88%B6%E5%AF%B9%E7%AD%96%22%5D%0A%20%20TAIL%20--%3E%20COST%5B%22%E6%88%90%E6%9C%AC%E5%AF%B9%E8%B4%A6%EF%BC%9ASLO%20%E7%BA%A6%E6%9D%9F%E4%B8%8B%E7%9A%84%E6%B0%B4%E4%BD%8D%22%5D%0A%20%20COST%20--%3E%7C%22%E8%B4%9F%E8%BD%BD%E5%BD%A2%E7%8A%B6%E5%8F%98%E4%BA%86%22%7C%20START%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[e("七课走完，三条骨架浮出来，它们不随服务、团队与云换。第一，"),a("strong",null,"一切主张带判据"),e("：数字、负载、环境、样本量，四样缺一就是修辞——需求四件套、基准的 run rules、排查的结案判据、成本账的可重算参数，是同一条纪律在四个环节的化身。第二，"),a("strong",null,"测量的是三元组"),e("：代码加平台加状态；平台与状态不受控时一切对比作废——排查先排环境、容量先钉负载形状、追尾先切维度，全是这一条在不同场景的重放。第三，"),a("strong",null,"预算同构"),e("：错误预算、容量余量、成本水位是同一笔钱的三种记法，花哪一份都要在分位上拿收据。两个公式跨课出现：Amdahl 给收益封顶，封住微基准的乐观与成本优化的账目；Little 给在途账，容量与连接池都按它配。排队发散与扇出的 max 放大则解释了尾为什么伤人、为什么削变异比堆机器便宜。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"一个可携带的自查单，四个问题对应三条骨架：这个主张有数字与负载模型吗？环境受控、样本量事先定了吗？改动花了哪份预算、在哪个分位上验的收据？结案判据写进文档了吗？四个「是」之前，任何优化都只是候选。")],-1)),(A(),t(n,null,{default:B(()=>[l(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20STAY%5B%22%E7%95%99%E5%9C%A8%E5%8E%9F%E5%9C%B0%E7%9A%84%EF%BC%9A%E5%9C%BA%E6%99%AF%E7%BB%91%E5%AE%9A%E7%9F%A5%E8%AF%86%22%5D%0A%20%20%20%20T1%5B%22%E5%9B%BA%E5%AE%9A%E6%B0%B4%E4%BD%8D%2070%25%22%5D%0A%20%20%20%20T2%5B%22%E6%9F%90%E6%AC%BE%20profiler%22%5D%0A%20%20%20%20T3%5B%22p99%20%E4%B8%80%E5%BE%8B%20200%20ms%22%5D%0A%20%20end%0A%20%20subgraph%20TAKE%5B%22%E5%B8%A6%E5%BE%97%E8%B5%B0%E7%9A%84%EF%BC%9A%E4%B8%89%E6%9D%A1%E9%AA%A8%E6%9E%B6%22%5D%0A%20%20%20%20K1%5B%22%E4%B8%BB%E5%BC%A0%E5%B8%A6%E5%88%A4%E6%8D%AE%EF%BC%9A%E6%95%B0%E5%AD%97%E3%80%81%E8%B4%9F%E8%BD%BD%E3%80%81%E7%8E%AF%E5%A2%83%E3%80%81%E6%A0%B7%E6%9C%AC%E9%87%8F%22%5D%0A%20%20%20%20K2%5B%22%E6%B5%8B%E7%9A%84%E6%98%AF%E4%B8%89%E5%85%83%E7%BB%84%EF%BC%9A%E4%BB%A3%E7%A0%81%E5%8A%A0%E5%B9%B3%E5%8F%B0%E5%8A%A0%E7%8A%B6%E6%80%81%22%5D%0A%20%20%20%20K3%5B%22%E9%A2%84%E7%AE%97%E5%90%8C%E6%9E%84%EF%BC%9A%E9%94%99%E8%AF%AF%E9%A2%84%E7%AE%97%E3%80%81%E5%AE%B9%E9%87%8F%E4%BD%99%E9%87%8F%E3%80%81%E6%88%90%E6%9C%AC%E6%B0%B4%E4%BD%8D%22%5D%0A%20%20end%0A%20%20TAKE%20--%3E%7C%22%E6%8D%A2%E8%B4%9F%E8%BD%BD%E3%80%81%E6%8D%A2%E7%A1%AC%E4%BB%B6%E3%80%81%E6%8D%A2%E4%BA%91%E4%B9%8B%E5%90%8E%22%7C%20NEW%5B%22%E9%87%8D%E5%AE%9A%E4%BB%B7%E5%87%BA%E6%96%B0%E7%9A%84%E6%B0%B4%E4%BD%8D%E4%B8%8E%E5%B7%A5%E5%85%B7%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=s('<p>这张图回答的问题是：哪些东西换一家公司就作废，哪些不？左边一列全是「别处的答案」——别人场景里的数字抄来即错；右边一列是产生答案的方法。骨架不是让你免于定数字，而是保证每次换环境后，能用同一套流程重新定出属于新场景的数字。</p><p><span class="marginnote">直觉类比（预算同构）：错误预算、容量余量、成本水位像同一张信用卡的三个记账科目——追求速度、扛住突发、压低账单，花的都是「风险承受力」这笔钱。区别只在刷卡场景，共同点是每次消费都要在某个分位上拿回一张收据。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程不替代机制课：墙为什么存在，归<a href="/cs/par-roofline-map">roofline 的深化与收束</a>的带宽-算力账与体系结构课；证据从哪来，归<a href="/cs/obs-perf-deep">perf 的深化</a>的计数器与采样、<a href="/cs/obs-flamegraphs">火焰图</a>的投影纪律、GPU 侧的<a href="/cs/gpu-profiling">性能计数与 profiling</a>；尾的机制与对策细节归<a href="/cs/tail-at-scale">Tail at Scale</a>与<a href="/cs/obs-slo-engineering">SLO 工程</a>。本课程给的是把这些机制钉进交付流程的方法：先有判据，才有优化；先控环境，才有对比；先有预算，才有花法。八课的案例是复合的，数字为教学构造，纪律是真实的。本课程到此收束。</p><p><span class="marginnote">常见误区：以为性能工程是「优化技巧的收集」。实际上技巧只是弹药，本课程给的准星——没有判据时，最强的优化技巧也只是在错误的负载上把错误的指标调快；有判据时，一个平凡的改动也能带着证据立项、结案、防回退。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>七课拼成一个周期：定需求、搭测量、查回归、算容量、追长尾、对成本；负载一变，回到第一课。</li><li>三条骨架跨场景成立：一切主张带判据、测量的是三元组、预算同构。</li><li>Amdahl 与 Little 是跨课的两个公式：一个封收益上限，一个配在途资源。</li><li>换环境带走的是纪律不是工具名与固定数字；水位与阈值都要随负载模型重定价。</li><li>出处：Jain，<em>The Art of Computer Systems Performance Analysis</em>，1991；Beyer 等，<em>Site Reliability Engineering</em>，2016；Dean 与 Barroso，<em>The Tail at Scale</em>，CACM 2013；据本课程八课口径整理。</li></ul>',7))])}const T=o(m,[["render",c]]);export{g as __pageData,T as default};
